export type { CycleHireDock } from "@/lib/tfl/cycle-hire-types";
export {
  CYCLE_HIRE_BIKE,
  CYCLE_HIRE_BROKEN,
  CYCLE_HIRE_EBIKE,
} from "@/components/tfl/cycle-hire/cycle-hire-colours";
export {
  CycleHireDockMarker,
  getDockCounts,
} from "@/components/tfl/cycle-hire/cycle-hire-dock-marker";
export {
  DEFAULT_CYCLE_HIRE_DOCK_IDS,
  CycleHireDocksBoardHeader,
  CycleHireDocksBoardSkeleton,
  CycleHireDockRow,
  CycleHireDocksDetail,
  CycleHireDocksBoard,
} from "@/components/tfl/cycle-hire/cycle-hire-docks-detail";
export { CycleHireDocksMap } from "@/components/tfl/cycle-hire/cycle-hire-docks-map";
export {
  CYCLE_HIRE_MAP_ATTRIBUTION_FALLBACK_PX,
  CYCLE_HIRE_MAP_EDGE_BREATHING_PX,
  CYCLE_HIRE_MAP_FRAME_CLASSNAME,
  CYCLE_HIRE_MAP_HOME_FRAME_CLASSNAME,
  CYCLE_HIRE_MAP_LABEL_FONT_SIZE_PX,
  CYCLE_HIRE_MAP_LABEL_MAX_LINES,
  CYCLE_HIRE_MAP_LABEL_WIDTH_PX,
  CYCLE_HIRE_MAP_NAV_RIGHT_PX,
  CYCLE_HIRE_MAP_PIN_LABEL_GAP_PX,
  clampCycleHireFitPadding,
  cycleHireFitPadding,
  cycleHireLabelRect,
  estimateCycleHirePinExtent,
  resolveCycleHireLabelSides,
} from "@/components/tfl/cycle-hire/cycle-hire-map-camera";
export type {
  CycleHireFitPaddingOptions,
  CycleHireLabelSide,
  CycleHireMapEdgePadding,
  CycleHirePinExtent,
  CycleHireScreenPin,
} from "@/components/tfl/cycle-hire/cycle-hire-map-camera";
export {
  CycleHireDocksProvider,
  useCycleHireDocksData,
} from "@/components/tfl/cycle-hire/cycle-hire-docks-context";
export { CycleHireDocks } from "@/components/tfl/cycle-hire/cycle-hire-docks-root";

/**
 * Cycle hire occupancy accents — tuned for light UI on light backgrounds.
 * Match Tailwind: red-500, cyan-400, amber-300.
 */
export const CYCLE_HIRE_BIKE = "oklch(63.7% 0.237 25.331)";
export const CYCLE_HIRE_EBIKE = "oklch(78.9% 0.154 211.53)";
export const CYCLE_HIRE_BROKEN = "oklch(87.9% 0.169 91.605)";

export const cycleHireBikeTextClass = "text-red-500";
export const cycleHireEbikeTextClass = "text-cyan-400";
export const cycleHireBrokenTextClass = "text-amber-300";

export const cycleHireBikeFillClass = "bg-red-500";
export const cycleHireEbikeFillClass = "bg-cyan-400";
export const cycleHireBrokenFillClass = "bg-amber-300";

import { Bike } from "lucide-react";
import { cn } from "@/lib/utils";
import type { CycleHireDock } from "@/lib/tfl/cycle-hire-types";
import {
  CYCLE_HIRE_BIKE,
  CYCLE_HIRE_EBIKE,
} from "@/components/tfl/cycle-hire/cycle-hire-colours";

export type { CycleHireDock } from "@/lib/tfl/cycle-hire-types";

export type DockCounts = {
  eBikes: number;
  standardBikes: number;
  brokenDocks: number;
  emptyDocks: number;
  totalDocks: number;
  availableBikes: number;
};

export const getDockCounts = (dock: CycleHireDock): DockCounts => {
  const totalDocks = Math.max(0, dock.docks);
  const eBikes = Math.max(0, dock.eBikes ?? 0);
  const standardBikes = Math.max(
    0,
    dock.standardBikes ?? Math.max(0, dock.bikes - eBikes),
  );
  const brokenDocks = Math.max(0, dock.brokenDocks);
  const emptyDocks = Math.max(
    0,
    dock.spaces ??
      Math.max(0, totalDocks - eBikes - standardBikes - brokenDocks),
  );
  return {
    eBikes,
    standardBikes,
    brokenDocks,
    emptyDocks,
    totalDocks,
    availableBikes: eBikes + standardBikes,
  };
};

type MarkerProps = {
  dock: CycleHireDock;
  className?: string;
  size?: number;
};

/**
 * Map-style dock marker — ring gauge for bike / e-bike / space, Lucide bike in the centre.
 * Broken docks are omitted (map glance info only).
 */
export const CycleHireDockMarker = ({
  dock,
  className,
  size = 56,
}: MarkerProps) => {
  const { standardBikes, eBikes, emptyDocks } = getDockCounts(dock);
  const total = standardBikes + eBikes + emptyDocks;

  const strokeWidth = Math.max(5, Math.round(size * 0.12));
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const centre = size / 2;

  const arcs =
    total === 0
      ? []
      : (
          [
            { kind: "standard" as const, count: standardBikes, colour: CYCLE_HIRE_BIKE },
            { kind: "eBike" as const, count: eBikes, colour: CYCLE_HIRE_EBIKE },
            {
              kind: "empty" as const,
              count: emptyDocks,
              colour: "var(--muted-foreground)",
            },
          ] as const
        ).filter((arc) => arc.count > 0);

  let offset = 0;

  return (
    <div
      className={cn("relative shrink-0", className)}
      style={{ width: size, height: size }}
      role="img"
      aria-label={
        total === 0
          ? `${dock.name}: no docks reported`
          : `${dock.name}: ${standardBikes} bikes, ${eBikes} e-bikes, ${emptyDocks} spaces`
      }
    >
      <svg
        width={size}
        height={size}
        viewBox={`0 0 ${size} ${size}`}
        className="block"
        aria-hidden
      >
        {total === 0 ? (
          <circle
            cx={centre}
            cy={centre}
            r={radius}
            fill="none"
            stroke="currentColor"
            strokeWidth={strokeWidth}
            className="text-muted"
          />
        ) : (
          arcs.map((arc) => {
            const length = (arc.count / total) * circumference;
            const dashOffset = -offset;
            offset += length;
            return (
              <circle
                key={arc.kind}
                cx={centre}
                cy={centre}
                r={radius}
                fill="none"
                stroke={arc.colour}
                strokeWidth={strokeWidth}
                strokeDasharray={`${length} ${circumference - length}`}
                strokeDashoffset={dashOffset}
                strokeLinecap="butt"
                transform={`rotate(-90 ${centre} ${centre})`}
                opacity={arc.kind === "empty" ? 0.35 : 1}
              />
            );
          })
        )}
        <circle
          cx={centre}
          cy={centre}
          r={radius - strokeWidth / 2 - 1}
          className="fill-background"
        />
      </svg>
      <Bike
        className="absolute top-1/2 left-1/2 size-[45%] -translate-x-1/2 -translate-y-1/2 text-foreground"
        strokeWidth={2}
        aria-hidden
      />
    </div>
  );
};

import { type ReactNode } from "react";
import Link from "next/link";
import { cn } from "@/lib/utils";
import { TfLRoundel } from "@/components/tfl/brand/tfl-roundel";
import { Skeleton } from "@/components/ui/skeleton";
import type { CycleHireDock } from "@/lib/tfl/cycle-hire-types";
import { getDockCounts } from "@/components/tfl/cycle-hire/cycle-hire-dock-marker";
import {
  cycleHireBikeFillClass,
  cycleHireBikeTextClass,
  cycleHireBrokenFillClass,
  cycleHireBrokenTextClass,
  cycleHireEbikeFillClass,
  cycleHireEbikeTextClass,
} from "@/components/tfl/cycle-hire/cycle-hire-colours";

export const DEFAULT_CYCLE_HIRE_DOCK_IDS = [
  "BikePoints_237",
  "BikePoints_490",
  "BikePoints_46",
] as const;

type SlotKind = "standard" | "eBike" | "empty" | "broken";

/** One cell per dock slot so `gap-*` reads between every slot, not only kind changes. */
const buildOccupancySlots = (
  counts: ReturnType<typeof getDockCounts>,
  showBroken: boolean,
): SlotKind[] => {
  const { standardBikes, eBikes, emptyDocks, brokenDocks } = counts;
  const slots: SlotKind[] = [];
  for (let i = 0; i < standardBikes; i += 1) slots.push("standard");
  for (let i = 0; i < eBikes; i += 1) slots.push("eBike");
  for (let i = 0; i < emptyDocks; i += 1) slots.push("empty");
  if (showBroken) {
    for (let i = 0; i < brokenDocks; i += 1) slots.push("broken");
  }
  return slots;
};

const slotFillClass = (kind: SlotKind) => {
  if (kind === "standard") return cycleHireBikeFillClass;
  if (kind === "eBike") return cycleHireEbikeFillClass;
  if (kind === "broken") return cycleHireBrokenFillClass;
  if (kind === "empty") return "bg-muted-foreground/25";
  return undefined;
};

export const CycleHireDocksBoardHeader = () => (
  <div className="flex flex-wrap items-center justify-between gap-2">
    <div className="flex items-center gap-3">
      <TfLRoundel variant="cycles" className="size-10 lg:size-12" />
      <div>
        <h1 className="scroll-m-20 text-balance text-4xl font-extrabold lg:text-5xl">
          Cycle hire docks
        </h1>
        <p className="mt-1 text-sm text-muted-foreground">
          Santander Cycles availability via{" "}
          <code className="rounded bg-muted px-1 py-0.5 text-xs">tfl-ts</code>
        </p>
      </div>
    </div>
  </div>
);

type SkeletonProps = {
  dockCount?: number;
};

export const CycleHireDocksBoardSkeleton = ({
  dockCount = DEFAULT_CYCLE_HIRE_DOCK_IDS.length,
}: SkeletonProps) => (
  <div
    className="flex w-full flex-col gap-6"
    aria-busy
    aria-label="Loading cycle hire docks"
  >
    {Array.from({ length: dockCount }).map((_, i) => (
      <div key={i} className="flex flex-col gap-2">
        <Skeleton className="h-5 w-48 max-w-full" />
        <Skeleton className="h-4 w-full" />
        <Skeleton className="h-3 w-40" />
      </div>
    ))}
  </div>
);

type DockRowProps = {
  dock: CycleHireDock;
  className?: string;
  showBroken?: boolean;
};

export const CycleHireDockRow = ({
  dock,
  className,
  showBroken = false,
}: DockRowProps) => {
  const counts = getDockCounts(dock);
  const { eBikes, standardBikes, brokenDocks, emptyDocks, totalDocks } =
    counts;

  if (totalDocks === 0) {
    return (
      <div className={cn("flex flex-col gap-1", className)}>
        <h3 className="text-sm font-semibold text-foreground">{dock.name}</h3>
        <p className="text-xs text-muted-foreground">No docks reported</p>
      </div>
    );
  }

  const slots = buildOccupancySlots(counts, showBroken);
  const showBrokenCount = showBroken && brokenDocks > 0;

  const ariaParts = [
    `${standardBikes} bikes`,
    `${eBikes} e-bikes`,
    `${emptyDocks} spaces`,
    showBrokenCount ? `${brokenDocks} broken` : null,
  ].filter(Boolean);

  return (
    <div
      className={cn("flex flex-col gap-2", className)}
    >
      <div className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1">
        <h3 className="text-sm font-semibold text-foreground">{dock.name}</h3>
        <div className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
          {dock.isLocked ? (
            <span className="font-medium text-destructive">Locked</span>
          ) : null}
          {dock.isTemporary ? (
            <span className="font-medium text-sky-600 dark:text-sky-400">
              Temporary
            </span>
          ) : null}
        </div>
      </div>

      <div
        className="flex h-4 w-full gap-0.5"
        role="img"
        aria-label={`${dock.name}: ${ariaParts.join(", ")}`}
      >
        {slots.map((kind, index) => (
          <div
            key={`${dock.id}-${kind}-${index}`}
            className={cn("min-w-0 flex-1", slotFillClass(kind))}
          />
        ))}
      </div>

      <div className="flex items-baseline justify-between gap-4 text-xs font-medium tracking-wide uppercase">
        <div className="flex flex-wrap items-baseline gap-x-3 gap-y-1">
          {standardBikes > 0 ? (
            <span className={cycleHireBikeTextClass}>
              {standardBikes} bikes
            </span>
          ) : null}
          {eBikes > 0 ? (
            <span className={cycleHireEbikeTextClass}>{eBikes} ebikes</span>
          ) : null}
          {showBrokenCount ? (
            <span className={cycleHireBrokenTextClass}>
              {brokenDocks} broken
            </span>
          ) : null}
          {standardBikes === 0 && eBikes === 0 && !showBrokenCount ? (
            <span className="text-muted-foreground normal-case tracking-normal">
              No bikes
            </span>
          ) : null}
        </div>
        <span className="shrink-0 text-muted-foreground">
          {emptyDocks} spaces
        </span>
      </div>
    </div>
  );
};

type DetailProps = {
  /** Normalised bike points. Omit when rendered under `CycleHireDocks` / Provider. */
  data?: readonly CycleHireDock[];
  children?: ReactNode;
  hideHeader?: boolean;
  statusLabel?: string;
  showBroken?: boolean;
  className?: string;
};

/**
 * Detail surface — occupancy bars + TfL-style counts.
 * Pass `data` explicitly, or nest under `CycleHireDocks` / Provider.
 * Wrap in Sheet / card chrome in the app if needed.
 */
export const CycleHireDocksDetail = ({
  data,
  hideHeader = false,
  statusLabel,
  showBroken = false,
  className,
  children,
}: DetailProps) => {
  const docks = data ?? [];

  return (
    <div className={cn("flex w-full flex-col gap-6", className)}>
      {!hideHeader && <CycleHireDocksBoardHeader />}

      {statusLabel ? (
        <p className="text-xs text-muted-foreground">{statusLabel}</p>
      ) : null}

      {docks.length === 0 ? (
        <p className="text-sm text-muted-foreground">No docks to show.</p>
      ) : (
        <div className="flex flex-col gap-5">
          {docks.map((dock) => (
            <CycleHireDockRow
              key={dock.id}
              dock={dock}
              showBroken={showBroken}
            />
          ))}
        </div>
      )}

      <div className="text-center text-sm text-muted-foreground">
        <p className="text-balance">
          Data from Transport for London via{" "}
          <Link
            href="https://www.npmjs.com/package/tfl-ts"
            className="text-blue-500 hover:underline"
          >
            tfl-ts
          </Link>
          . Pass normalised rows as <code className="text-xs">data</code>.
        </p>
      </div>

      {children}
    </div>
  );
};

/** @deprecated Prefer `CycleHireDocksDetail`. */
export const CycleHireDocksBoard = CycleHireDocksDetail;

"use client";

import { useEffect, useRef, useSyncExternalStore } from "react";
import { createRoot, type Root } from "react-dom/client";
import { flushSync } from "react-dom";
import maplibregl from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";
import { cn } from "@/lib/utils";
import type { CycleHireDock } from "@/lib/tfl/cycle-hire-types";
import { useCycleHireDocksData } from "@/components/tfl/cycle-hire/cycle-hire-docks-context";
import { CycleHireDockMarker } from "@/components/tfl/cycle-hire/cycle-hire-dock-marker";
import {
  CYCLE_HIRE_MAP_ATTRIBUTION_FALLBACK_PX,
  CYCLE_HIRE_MAP_FRAME_CLASSNAME,
  CYCLE_HIRE_MAP_LABEL_FONT_SIZE_PX,
  CYCLE_HIRE_MAP_LABEL_WIDTH_PX,
  clampCycleHireFitPadding,
  cycleHireFitPadding,
  resolveCycleHireLabelSides,
  type CycleHireLabelSide,
  type CycleHireMapEdgePadding,
} from "@/components/tfl/cycle-hire/cycle-hire-map-camera";
import { StationName } from "@/components/tfl/station-name";

/** OpenFreeMap vector styles — inlined so the registry stays self-contained. */
const OPENFREEMAP_POSITRON_STYLE_URL =
  "https://tiles.openfreemap.org/styles/positron";
const OPENFREEMAP_DARK_STYLE_URL =
  "https://tiles.openfreemap.org/styles/dark";
const openFreeMapStyleUrl = (dark: boolean) =>
  dark ? OPENFREEMAP_DARK_STYLE_URL : OPENFREEMAP_POSITRON_STYLE_URL;

const subscribeDocumentDark = (onStoreChange: () => void) => {
  const observer = new MutationObserver(onStoreChange);
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ["class"],
  });
  return () => observer.disconnect();
};
const getDocumentDark = () =>
  document.documentElement.classList.contains("dark");
const LONDON_CENTER: [number, number] = [-0.08, 51.507];
const FALLBACK_ZOOM = 13;
const SINGLE_DOCK_ZOOM = 15;
const MULTI_DOCK_MAX_ZOOM = 16;

type MapPadding = number | CycleHireMapEdgePadding;

type MapProps = {
  /** Normalised bike points. Omit when rendered under `CycleHireDocks` / Provider. */
  data?: readonly CycleHireDock[];
  className?: string;
  /** Marker diameter in px. */
  markerSize?: number;
  /** Zoom controls (default true). Hide on compact proof surfaces. */
  showNavigation?: boolean;
  /**
   * Optional `fitBounds` padding override. When omitted, padding is derived
   * from measured pin + label + attribution via `cycleHireFitPadding`.
   */
  fitPadding?: MapPadding;
};

type MarkerEntry = {
  marker: maplibregl.Marker;
  root: Root;
  dock: CycleHireDock & { lat: number; lon: number };
  labelSide: CycleHireLabelSide;
};

/** Defer createRoot unmount — sync unmount during React render/cleanup races. */
const disposeMarkerEntry = (entry: MarkerEntry) => {
  entry.marker.remove();
  queueMicrotask(() => {
    entry.root.unmount();
  });
};

const hasCoordinates = (
  dock: CycleHireDock,
): dock is CycleHireDock & { lat: number; lon: number } =>
  typeof dock.lat === "number" &&
  Number.isFinite(dock.lat) &&
  typeof dock.lon === "number" &&
  Number.isFinite(dock.lon);

const DockMapPin = ({
  dock,
  size,
  labelSide,
}: {
  dock: CycleHireDock;
  size: number;
  labelSide: CycleHireLabelSide;
}) => (
  <div className="relative" style={{ width: size, height: size }}>
    <CycleHireDockMarker dock={dock} size={size} />
    <div
      className={cn(
        "absolute left-1/2 z-1 -translate-x-1/2 bg-background/90 leading-none shadow-sm",
        labelSide === "below" ? "top-full mt-0.5" : "bottom-full mb-0.5",
      )}
      style={{ width: CYCLE_HIRE_MAP_LABEL_WIDTH_PX }}
    >
      <StationName
        name={dock.name}
        layout="auto"
        maxWidth={CYCLE_HIRE_MAP_LABEL_WIDTH_PX}
        fontSize={CYCLE_HIRE_MAP_LABEL_FONT_SIZE_PX}
        maxLines={2}
        allowAbbreviation
        allowScaleDown
        align="center"
        className="h-auto font-sans font-medium leading-none text-foreground"
      />
    </div>
  </div>
);

const paintPin = (entry: MarkerEntry, markerSize: number) => {
  entry.root.render(
    <DockMapPin
      dock={entry.dock}
      size={markerSize}
      labelSide={entry.labelSide}
    />,
  );
};

const measureAttributionHeight = (container: HTMLElement): number => {
  const attrib = container.querySelector(".maplibregl-ctrl-attrib");
  if (!(attrib instanceof HTMLElement)) {
    return CYCLE_HIRE_MAP_ATTRIBUTION_FALLBACK_PX;
  }
  return Math.max(
    attrib.getBoundingClientRect().height,
    CYCLE_HIRE_MAP_ATTRIBUTION_FALLBACK_PX,
  );
};

const resolveFitPadding = (
  map: maplibregl.Map,
  container: HTMLElement,
  markerSize: number,
  showNavigation: boolean,
  fitPadding: MapPadding | undefined,
  labelClearance: "below" | "both" = "below",
): MapPadding => {
  if (fitPadding != null) return fitPadding;
  const padding = cycleHireFitPadding(markerSize, {
    showNavigation,
    labelClearance,
    attributionHeight: measureAttributionHeight(container),
  });
  const canvas = map.getCanvas();
  return clampCycleHireFitPadding(
    padding,
    canvas.clientWidth,
    canvas.clientHeight,
  );
};

const fitDocksCamera = (
  map: maplibregl.Map,
  located: readonly (CycleHireDock & { lat: number; lon: number })[],
  padding: MapPadding,
) => {
  if (located.length === 0) return;

  if (located.length === 1) {
    const [dock] = located;
    if (!dock) return;
    map.easeTo({
      center: [dock.lon, dock.lat],
      zoom: SINGLE_DOCK_ZOOM,
      padding,
      duration: 0,
    });
    return;
  }

  const bounds = new maplibregl.LngLatBounds();
  for (const dock of located) {
    bounds.extend([dock.lon, dock.lat]);
  }
  map.fitBounds(bounds, {
    padding,
    maxZoom: MULTI_DOCK_MAX_ZOOM,
    duration: 0,
  });
};

/**
 * OpenFreeMap vector Positron / MapLibre surface — circle-gauge markers at dock lat/lon.
 * Glance info only (bike / e-bike / space). Not linked to Detail selection.
 * Camera fits once when the map has a real size and docks are on the canvas.
 */
export const CycleHireDocksMap = ({
  data,
  className,
  markerSize = 48,
  showNavigation = true,
  fitPadding,
}: MapProps) => {
  const docks = useCycleHireDocksData(data);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const markersRef = useRef<MarkerEntry[]>([]);
  const hasFittedRef = useRef(false);
  const skipStyleSwapRef = useRef(true);
  const dark = useSyncExternalStore(
    subscribeDocumentDark,
    getDocumentDark,
    () => false,
  );

  useEffect(() => {
    const container = containerRef.current;
    if (!container || mapRef.current) return;

    const map = new maplibregl.Map({
      container,
      style: openFreeMapStyleUrl(dark),
      center: LONDON_CENTER,
      zoom: FALLBACK_ZOOM,
      attributionControl: { compact: true },
      cooperativeGestures: true,
    });

    if (showNavigation) {
      map.addControl(
        new maplibregl.NavigationControl({ showCompass: false }),
        "top-right",
      );
    }
    mapRef.current = map;
    hasFittedRef.current = false;

    return () => {
      for (const entry of markersRef.current) {
        disposeMarkerEntry(entry);
      }
      markersRef.current = [];
      map.remove();
      mapRef.current = null;
      hasFittedRef.current = false;
    };
    // Initial style from first `dark` snapshot; swaps happen below.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [showNavigation]);

  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    if (skipStyleSwapRef.current) {
      skipStyleSwapRef.current = false;
      return;
    }
    map.setStyle(openFreeMapStyleUrl(dark));
  }, [dark]);

  useEffect(() => {
    const map = mapRef.current;
    const container = containerRef.current;
    if (!map || !container) return;

    let cancelled = false;
    let observer: ResizeObserver | null = null;

    const syncMarkers = () => {
      const located = docks.filter(hasCoordinates);
      const nextById = new Map(located.map((dock) => [dock.id, dock]));
      const prevById = new Map(
        markersRef.current.map((entry) => [entry.dock.id, entry]),
      );

      for (const [id, entry] of prevById) {
        if (!nextById.has(id)) {
          disposeMarkerEntry(entry);
          markersRef.current = markersRef.current.filter(
            (item) => item.dock.id !== id,
          );
        }
      }

      const nextEntries: MarkerEntry[] = [];

      for (const dock of located) {
        const existing = prevById.get(dock.id);
        if (existing) {
          const moved =
            existing.dock.lat !== dock.lat || existing.dock.lon !== dock.lon;
          if (moved) {
            existing.marker.setLngLat([dock.lon, dock.lat]);
          }
          existing.dock = dock;
          paintPin(existing, markerSize);
          nextEntries.push(existing);
        } else {
          const el = document.createElement("div");
          const root = createRoot(el);
          const marker = new maplibregl.Marker({
            element: el,
            anchor: "center",
          })
            .setLngLat([dock.lon, dock.lat])
            .addTo(map);
          const entry: MarkerEntry = {
            marker,
            root,
            dock,
            labelSide: "below",
          };
          if (!hasFittedRef.current) {
            flushSync(() => {
              paintPin(entry, markerSize);
            });
          } else {
            paintPin(entry, markerSize);
          }
          nextEntries.push(entry);
        }
      }

      markersRef.current = nextEntries;
      return located;
    };

    const applyLabelSides = () => {
      if (cancelled) return;
      const canvas = map.getCanvas();
      const sides = resolveCycleHireLabelSides(
        markersRef.current.map((entry) => {
          const point = map.project([entry.dock.lon, entry.dock.lat]);
          return { id: entry.dock.id, x: point.x, y: point.y };
        }),
        {
          markerSize,
          mapWidth: canvas.clientWidth,
          mapHeight: canvas.clientHeight,
          attributionHeight: measureAttributionHeight(container),
        },
      );
      let flippedUp = false;
      for (const entry of markersRef.current) {
        const nextSide = sides.get(entry.dock.id) ?? "below";
        if (nextSide === "above") flippedUp = true;
        if (entry.labelSide === nextSide) continue;
        entry.labelSide = nextSide;
        paintPin(entry, markerSize);
      }
      return flippedUp;
    };

    const tryInitialFit = (
      located: readonly (CycleHireDock & { lat: number; lon: number })[],
    ) => {
      if (cancelled || hasFittedRef.current || located.length === 0) return true;
      const { width, height } = container.getBoundingClientRect();
      if (width < 2 || height < 2) return false;
      map.resize();
      const padding = resolveFitPadding(
        map,
        container,
        markerSize,
        showNavigation,
        fitPadding,
      );
      fitDocksCamera(map, located, padding);
      hasFittedRef.current = true;
      const flippedUp = applyLabelSides();
      if (flippedUp && fitPadding == null) {
        fitDocksCamera(
          map,
          located,
          resolveFitPadding(
            map,
            container,
            markerSize,
            showNavigation,
            undefined,
            "both",
          ),
        );
        applyLabelSides();
      }
      return true;
    };

    const run = () => {
      if (cancelled) return;
      const located = syncMarkers();
      if (tryInitialFit(located)) {
        observer?.disconnect();
        observer = null;
        return;
      }
      if (observer) return;
      observer = new ResizeObserver(() => {
        if (tryInitialFit(located)) {
          observer?.disconnect();
          observer = null;
        }
      });
      observer.observe(container);
    };

    if (map.isStyleLoaded()) {
      run();
    } else {
      map.once("load", run);
    }

    const handleMoveEnd = () => {
      if (!hasFittedRef.current) return;
      applyLabelSides();
    };
    map.on("moveend", handleMoveEnd);

    return () => {
      cancelled = true;
      observer?.disconnect();
      map.off("load", run);
      map.off("moveend", handleMoveEnd);
    };
  }, [docks, markerSize, fitPadding, showNavigation]);

  const locatedCount = docks.filter(hasCoordinates).length;

  return (
    <div
      ref={containerRef}
      className={cn("bg-muted", CYCLE_HIRE_MAP_FRAME_CLASSNAME, className)}
      role="region"
      aria-label={
        locatedCount === 0
          ? "Cycle hire map — no docks with coordinates"
          : `Cycle hire map — ${locatedCount} docks`
      }
    />
  );
};

/**
 * Cycle hire map camera + frame helpers (MapLibre-free — keep SDK in client surfaces).
 *
 * Markers use anchor `"center"`: the lng/lat is the pin centre. Labels are
 * absolutely positioned (CSS `position-try: flip-block` analogue): try below,
 * flip above when that box would hit another pin, another label, or the map
 * edge / attribution strip.
 *
 * Frame classes size the map *and* any skeleton the same way — map fills the
 * parent; the parent owns aspect / max-height so mobile pages can scroll past.
 */

/** Map pin label box — fit policy measures against this width. */
export const CYCLE_HIRE_MAP_LABEL_WIDTH_PX = 112;
export const CYCLE_HIRE_MAP_LABEL_FONT_SIZE_PX = 11;
export const CYCLE_HIRE_MAP_LABEL_MAX_LINES = 2;
/** Matches `gap-0.5` between pin and label. */
export const CYCLE_HIRE_MAP_PIN_LABEL_GAP_PX = 2;

/**
 * Default docs / preview frame: stable aspect, capped height on small viewports
 * so the map does not eat the whole scrollport.
 */
export const CYCLE_HIRE_MAP_FRAME_CLASSNAME =
  "aspect-[4/3] w-full max-h-[min(42svh,28rem)]";

/**
 * Homepage arrivals-rhythm frame — fixed tile height, no aspect (override the
 * default frame with `aspect-auto max-h-none` + this class on the parent).
 */
export const CYCLE_HIRE_MAP_HOME_FRAME_CLASSNAME =
  "h-[calc(var(--arrivals-row)*6)] w-full";

/** Breathing room past the pin/label box. */
export const CYCLE_HIRE_MAP_EDGE_BREATHING_PX = 8;
/** Compact MapLibre attribution strip (fallback when not measured). */
export const CYCLE_HIRE_MAP_ATTRIBUTION_FALLBACK_PX = 28;
/** NavigationControl width — applied on the right only. */
export const CYCLE_HIRE_MAP_NAV_RIGHT_PX = 40;

export type CycleHireMapEdgePadding = {
  top: number;
  bottom: number;
  left: number;
  right: number;
};

export type CycleHirePinExtent = {
  /** px above the lng/lat (half pin, plus label when flipped). */
  above: number;
  /** px below the lng/lat (half pin + gap + label when hanging down). */
  below: number;
  /** px left/right of the lng/lat to cover centred label (or pin). */
  halfWidth: number;
};

export type CycleHireLabelSide = "below" | "above";

export type CycleHireScreenPin = {
  id: string;
  x: number;
  y: number;
};

export type CycleHireFitPaddingOptions = {
  showNavigation?: boolean;
  above?: number;
  below?: number;
  halfWidth?: number;
  /** Measured attribution / bottom-control height. */
  attributionHeight?: number;
  /**
   * `"below"` (default): labels hang down — top padding is half the pin.
   * `"both"`: some labels flipped up — top padding includes a label box.
   */
  labelClearance?: "below" | "both";
};

type LabelBox = { left: number; top: number; width: number; height: number };

export const cycleHireLabelHeightPx = (): number =>
  CYCLE_HIRE_MAP_LABEL_FONT_SIZE_PX * CYCLE_HIRE_MAP_LABEL_MAX_LINES;

/** Pixel extent of one dock pin relative to its centre lng/lat. */
export const estimateCycleHirePinExtent = (
  markerSize: number,
  labelClearance: "below" | "both" = "below",
): CycleHirePinExtent => {
  const labelHeight = cycleHireLabelHeightPx();
  const halfPin = markerSize / 2;
  const labelStack = CYCLE_HIRE_MAP_PIN_LABEL_GAP_PX + labelHeight;
  return {
    above:
      labelClearance === "both" ? halfPin + labelStack : halfPin,
    below: halfPin + labelStack,
    halfWidth: Math.max(halfPin, CYCLE_HIRE_MAP_LABEL_WIDTH_PX / 2),
  };
};

export const cycleHireLabelRect = (
  pin: CycleHireScreenPin,
  side: CycleHireLabelSide,
  markerSize: number,
): LabelBox => {
  const radius = markerSize / 2;
  const height = cycleHireLabelHeightPx();
  const top =
    side === "below"
      ? pin.y + radius + CYCLE_HIRE_MAP_PIN_LABEL_GAP_PX
      : pin.y - radius - CYCLE_HIRE_MAP_PIN_LABEL_GAP_PX - height;
  return {
    left: pin.x - CYCLE_HIRE_MAP_LABEL_WIDTH_PX / 2,
    top,
    width: CYCLE_HIRE_MAP_LABEL_WIDTH_PX,
    height,
  };
};

const boxesOverlap = (a: LabelBox, b: LabelBox): boolean =>
  a.left < b.left + b.width &&
  a.left + a.width > b.left &&
  a.top < b.top + b.height &&
  a.top + a.height > b.top;

const circleHitsBox = (
  cx: number,
  cy: number,
  radius: number,
  box: LabelBox,
): boolean => {
  const nearestX = Math.max(box.left, Math.min(cx, box.left + box.width));
  const nearestY = Math.max(box.top, Math.min(cy, box.top + box.height));
  const dx = cx - nearestX;
  const dy = cy - nearestY;
  return dx * dx + dy * dy < radius * radius;
};

/**
 * CSS `position-try: flip-block` analogue: prefer below, flip above when that
 * box would cover another pin, overlap a placed label, or leave the map.
 */
export const resolveCycleHireLabelSides = (
  pins: readonly CycleHireScreenPin[],
  options: {
    markerSize: number;
    mapWidth: number;
    mapHeight: number;
    attributionHeight?: number;
  },
): Map<string, CycleHireLabelSide> => {
  const sides = new Map<string, CycleHireLabelSide>();
  const radius = options.markerSize / 2;
  const mapBottom =
    options.mapHeight - (options.attributionHeight ?? 0);
  const placed: LabelBox[] = [];

  const fits = (pin: CycleHireScreenPin, side: CycleHireLabelSide): boolean => {
    const box = cycleHireLabelRect(pin, side, options.markerSize);
    if (box.top < 0 || box.top + box.height > mapBottom) return false;
    if (box.left < 0 || box.left + box.width > options.mapWidth) return false;
    if (
      pins.some(
        (other) =>
          other.id !== pin.id &&
          circleHitsBox(other.x, other.y, radius, box),
      )
    ) {
      return false;
    }
    return !placed.some((other) => boxesOverlap(box, other));
  };

  const northFirst = [...pins].sort((a, b) => a.y - b.y);
  for (const pin of northFirst) {
    const side: CycleHireLabelSide =
      fits(pin, "below") || !fits(pin, "above") ? "below" : "above";
    sides.set(pin.id, side);
    placed.push(cycleHireLabelRect(pin, side, options.markerSize));
  }
  return sides;
};

/**
 * Asymmetric `fitBounds` padding so every pin + station label clears the
 * viewport, including the OSM attribution strip. Top is half the pin unless
 * labels may flip up (`labelClearance: "both"`).
 */
export const cycleHireFitPadding = (
  markerSize: number,
  options?: CycleHireFitPaddingOptions,
): CycleHireMapEdgePadding => {
  const estimated = estimateCycleHirePinExtent(
    markerSize,
    options?.labelClearance ?? "below",
  );
  const above = options?.above ?? estimated.above;
  const below = options?.below ?? estimated.below;
  const halfWidth = options?.halfWidth ?? estimated.halfWidth;
  const attribution =
    options?.attributionHeight ?? CYCLE_HIRE_MAP_ATTRIBUTION_FALLBACK_PX;
  const navRight =
    options?.showNavigation === true ? CYCLE_HIRE_MAP_NAV_RIGHT_PX : 0;

  return {
    top: CYCLE_HIRE_MAP_EDGE_BREATHING_PX + above,
    right: CYCLE_HIRE_MAP_EDGE_BREATHING_PX + halfWidth + navRight,
    bottom: CYCLE_HIRE_MAP_EDGE_BREATHING_PX + below + attribution,
    left: CYCLE_HIRE_MAP_EDGE_BREATHING_PX + halfWidth,
  };
};

/**
 * MapLibre rejects padding that fills the canvas. Keep the bottom-heavy ratio.
 */
export const clampCycleHireFitPadding = (
  padding: CycleHireMapEdgePadding,
  mapWidth: number,
  mapHeight: number,
): CycleHireMapEdgePadding => {
  const maxVertical = Math.max(0, mapHeight - 8);
  const maxHorizontal = Math.max(0, mapWidth - 8);
  const vertical = padding.top + padding.bottom;
  const horizontal = padding.left + padding.right;
  const vScale = vertical > maxVertical && vertical > 0 ? maxVertical / vertical : 1;
  const hScale =
    horizontal > maxHorizontal && horizontal > 0 ? maxHorizontal / horizontal : 1;
  return {
    top: padding.top * vScale,
    bottom: padding.bottom * vScale,
    left: padding.left * hScale,
    right: padding.right * hScale,
  };
};

"use client";

import {
  createContext,
  useContext,
  useMemo,
  type ReactNode,
} from "react";
import type { CycleHireDock } from "@/lib/tfl/cycle-hire-types";

type CycleHireDocksContextValue = {
  data: readonly CycleHireDock[];
};

const CycleHireDocksContext = createContext<CycleHireDocksContextValue | null>(
  null,
);

const EMPTY_DOCKS: readonly CycleHireDock[] = [];
const EMPTY_VALUE: CycleHireDocksContextValue = { data: EMPTY_DOCKS };

type ProviderProps = {
  data?: readonly CycleHireDock[];
  children: ReactNode;
};

/**
 * Optional shared-data parent for Map + Detail surfaces.
 * Prefer passing `data` explicitly on each surface when only one is mounted.
 */
export const CycleHireDocksProvider = ({
  data,
  children,
}: ProviderProps) => {
  const value = useMemo<CycleHireDocksContextValue>(
    () => (data == null ? EMPTY_VALUE : { data }),
    [data],
  );

  return (
    <CycleHireDocksContext.Provider value={value}>
      {children}
    </CycleHireDocksContext.Provider>
  );
};

/** Read docks from an explicit `data` prop, else the nearest Provider. */
export const useCycleHireDocksData = (
  data?: readonly CycleHireDock[],
): readonly CycleHireDock[] => {
  const ctx = useContext(CycleHireDocksContext);
  return data ?? ctx?.data ?? EMPTY_DOCKS;
};

