"use client";

import {
  Fragment,
  useEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import { cn } from "@/lib/utils";
import { FindableText } from "@/components/tfl/findable-text";
import {
  approximateStationMeasure,
  createCanvasStationMeasure,
  formatStationLabel,
  resolveSansFontFamily,
  type StationLabelFormatResult,
} from "@/lib/tfl/station-typography";
import { formatStationName } from "@/lib/tfl/diagram-station";
import {
  findCompletionForToken,
  stationCopyName,
  stationFindAliases,
  stationFindCoveredPhrases,
} from "@/lib/tfl/station-label-find";

export type StationNameLayout = "fixed" | "auto";

export type StationNameProps = {
  name: string;
  className?: string;
  style?: CSSProperties;
  /**
   * Explicit visual lines (editorial / crowding recipes).
   * When set, skips auto word-break selection.
   */
  lines?: readonly string[];
  /**
   * `fixed` (default): use `lines` or a single canonical line — no measure/scale.
   * `auto`: measure the box and pick 1–2 lines / abbr / scale via formatStationLabel.
   */
  layout?: StationNameLayout;
  /**
   * When set with `layout="auto"`, labels measure against this width instead
   * of the container. Useful for fixed diagram columns.
   */
  maxWidth?: number;
  fontSize?: number;
  maxLines?: 1 | 2;
  allowAbbreviation?: boolean;
  allowScaleDown?: boolean;
  minScale?: number;
  /**
   * @deprecated Prefer `lines`. Kept for call-site compatibility.
   */
  forcedLines?: readonly string[];
  /**
   * Canonical single-line name for aria + copy. Defaults to `formatStationName`.
   */
  accessibleName?: string;
  /**
   * @deprecated No longer required — find/copy/aria always use the canonical name.
   */
  abbreviatedVisual?: boolean;
  /** Align text within the label block. */
  align?: "left" | "center" | "right";
  /** Expose format diagnostics to a parent (typography lab). */
  onFormat?: (result: StationLabelFormatResult) => void;
};

/** @deprecated Use `StationNameProps`. */
export type StationNameLabelProps = StationNameProps;

type SizeState = {
  width: number;
  fontSize: number;
  fontFamily: string;
  measured: boolean;
};

const WIDTH_EPSILON = 0.5;
const FONT_EPSILON = 0.05;
const FALLBACK_FONT = "Hammersmith One, system-ui, sans-serif";
/** Unitless so wrapped lines stay clustered when `scale` shrinks font-size. */
const MULTILINE_LINE_HEIGHT = 1.15;

/**
 * Invisible inline completion (e.g. St + "reet" → Street) for engines that
 * still index font-size: 0. Primary cross-line find uses FindPhrase below.
 */
const FindExpand = ({ text }: { text: string }) => (
  <span className="text-[0px] leading-none" aria-hidden="true">
    {text}
  </span>
);

const renderFindableLine = (line: string): ReactNode[] =>
  line.split(/(\s+|&)/).map((part, index) => {
    if (!part) return null;
    const completion = findCompletionForToken(part);
    if (!completion) {
      return <Fragment key={`${part}-${index}`}>{part}</Fragment>;
    }
    return (
      <Fragment key={`${part}-${index}`}>
        {part}
        <FindExpand text={completion} />
      </Fragment>
    );
  });

const fixedResult = (
  name: string,
  lines?: readonly string[],
): StationLabelFormatResult => {
  const displayName = formatStationName(name);
  if (lines && lines.length > 0) {
    return {
      lines: [...lines],
      scale: 1,
      abbreviated: lines.join(" ") !== displayName,
      fits: true,
      displayName,
    };
  }
  return {
    lines: [displayName],
    scale: 1,
    abbreviated: false,
    fits: true,
    displayName,
  };
};

/**
 * Station name UI contract: canonical copy / aria, find-in-page variants,
 * and optional visual line breaks. String-driven so non-TfL labels (pubs,
 * attractions) can use the same find/copy behaviour.
 *
 * Diagrams typically pass `lines` from a label recipe with `layout="fixed"`.
 * The typography lab uses `layout="auto"` + `maxWidth` to exercise fit policy.
 */
export const StationName = ({
  name,
  className,
  style,
  lines: linesProp,
  layout = "fixed",
  maxWidth: maxWidthProp,
  fontSize: fontSizeProp,
  maxLines = 2,
  allowAbbreviation = false,
  allowScaleDown = true,
  minScale,
  forcedLines,
  accessibleName: accessibleNameProp,
  align = "left",
  onFormat,
}: StationNameProps) => {
  const ref = useRef<HTMLSpanElement>(null);
  const visualLines = linesProp ?? forcedLines;
  const useAuto = layout === "auto";
  const hasFixedMetrics =
    useAuto && maxWidthProp != null && maxWidthProp > 0 && fontSizeProp != null;
  const copyName = stationCopyName(name, accessibleNameProp);

  const [size, setSize] = useState<SizeState>(() => ({
    width: maxWidthProp ?? 0,
    fontSize: fontSizeProp ?? 16,
    fontFamily: FALLBACK_FONT,
    measured: false,
  }));

  useEffect(() => {
    if (!useAuto) return;
    const el = ref.current;
    if (!el) return;

    let cancelled = false;
    const container = el.parentElement;

    const readMetrics = () => {
      if (cancelled) return;

      const width =
        maxWidthProp ??
        (container && container.clientWidth > 0
          ? container.clientWidth
          : el.clientWidth);

      const measuredFont =
        fontSizeProp ??
        (Number.parseFloat(getComputedStyle(el).fontSize) || 16);
      const fontFamily = resolveSansFontFamily(el);

      setSize((prev) => {
        if (
          prev.measured &&
          Math.abs(prev.width - width) < WIDTH_EPSILON &&
          Math.abs(prev.fontSize - measuredFont) < FONT_EPSILON &&
          prev.fontFamily === fontFamily
        ) {
          return prev;
        }
        return {
          width,
          fontSize: measuredFont,
          fontFamily,
          measured: true,
        };
      });
    };

    const waitFonts = async () => {
      try {
        if (document.fonts?.ready) await document.fonts.ready;
      } catch {
        // Ignore font loading errors; approximate measure still works.
      }
      readMetrics();
    };

    void waitFonts();

    const observer = new ResizeObserver(() => readMetrics());
    if (container) observer.observe(container);
    else observer.observe(el);

    return () => {
      cancelled = true;
      observer.disconnect();
    };
  }, [fontSizeProp, maxWidthProp, name, useAuto]);

  const measure = useMemo(() => {
    if (!useAuto || !size.measured) return approximateStationMeasure;
    return createCanvasStationMeasure(size.fontFamily);
  }, [size.fontFamily, size.measured, useAuto]);

  const formatOptions = useMemo(
    () => ({
      maxWidth: Math.max(size.width, 1),
      fontSize: size.fontSize,
      maxLines,
      allowAbbreviation,
      allowScaleDown,
      minScale,
      forcedLines: visualLines,
    }),
    [
      allowAbbreviation,
      allowScaleDown,
      visualLines,
      maxLines,
      minScale,
      size.fontSize,
      size.width,
    ],
  );

  const result = useMemo(() => {
    if (!useAuto) return fixedResult(name, visualLines);

    // Unmeasured (or a ~0px slot) stays at full size. Pretending the box is
    // 1px wide forced minScale on every first paint, then a shrink-wrapped
    // parent ratcheted that small size even when the heading had room.
    // Tiles clip overflow; scale down only after a real slot width exists.
    if (!hasFixedMetrics && (!size.measured || size.width <= 4)) {
      return fixedResult(name, visualLines);
    }
    return formatStationLabel(name, measure, formatOptions);
  }, [
    formatOptions,
    hasFixedMetrics,
    measure,
    name,
    size.measured,
    size.width,
    useAuto,
    visualLines,
  ]);

  useEffect(() => {
    if (!useAuto) {
      onFormat?.(result);
      return;
    }
    if (!size.measured || size.width <= 0) return;
    onFormat?.(result);
  }, [onFormat, result, size.measured, size.width, useAuto]);

  const coveredPhrases = useMemo(
    () => stationFindCoveredPhrases(result.lines),
    [result.lines],
  );
  const findAliases = useMemo(
    () => stationFindAliases(copyName, result.lines),
    [copyName, result.lines],
  );

  const textAlign =
    align === "center" ? "center" : align === "right" ? "right" : "left";
  const multiline = result.lines.length > 1;

  const paintDiffersFromCopy =
    multiline ||
    result.abbreviated ||
    result.lines.join(" ").replace(/\s+/g, " ").trim() !== copyName;
  const extraFindAliases = findAliases.filter(
    (alias) => alias.toLowerCase() !== copyName.toLowerCase(),
  );

  return (
    <FindableText
      ref={ref}
      text={copyName}
      aliases={extraFindAliases}
      coveredPhrases={coveredPhrases}
      paintMatchesText={!paintDiffersFromCopy}
      className={cn(
        "relative inline-flex h-full min-h-0 w-full min-w-0 flex-col justify-center",
        useAuto && maxWidthProp == null && "flex-1",
        !multiline && "leading-none",
        align === "center" && "items-center",
        align === "right" && "items-end",
        align === "left" && "items-start",
        className,
      )}
      style={{
        ...style,
        fontSize: fontSizeProp != null ? `${fontSizeProp}px` : style?.fontSize,
        textAlign,
      }}
    >
      <span
        className="inline-block w-full min-w-0"
        style={{
          fontSize: result.scale !== 1 ? `${result.scale * 100}%` : undefined,
          // Unitless LH tracks scaled font-size; rem leading from callers would not.
          lineHeight: multiline ? MULTILINE_LINE_HEIGHT : undefined,
        }}
        aria-hidden="true"
        // `layout="auto"` intentionally repaints once the box is measured
        // (approximate → canvas fit can pick a different line break/scale
        // than the pre-measure guess). That's a post-hydration update, not a
        // markup mismatch, but suppress the warning on this node only —
        // never on the whole component — since the two passes can render
        // different characters/line breaks for the same props.
        suppressHydrationWarning={useAuto}
      >
        {result.lines.map((line, index) => (
          <Fragment key={`${line}-${index}`}>
            {index > 0 ? (
              <>
                <FindExpand text=" " />
                <br />
              </>
            ) : null}
            <span className="whitespace-nowrap">
              {renderFindableLine(line)}
            </span>
          </Fragment>
        ))}
      </span>
    </FindableText>
  );
};

/**
 * Flex slot for board identity titles (stop name, cycle area, status group).
 * `layout="auto"` measures this box — it must be a flex item with a definite
 * width (`flex-1 min-w-0`), not shrink-wrapped to the glyphs.
 */
export const STATION_NAME_TITLE_SLOT_CLASS =
  "flex h-full min-w-0 flex-1 items-center";

/**
 * Trim the line box to cap-height → alphabetic baseline (not full
 * ascent/descent) before centering. A title is a label for what sits below
 * it, not what's above — centering on cap-height (rather than including
 * descender space) reads as anchored to its content and nudges the glyphs
 * down a touch versus dead-center. Same technique as chip labels
 * (`CHIP_CAP_TEXT_BOX_CLASS`), applied here at title scale.
 */
const STATION_NAME_TITLE_CLASS =
  "justify-center leading-none [text-box:trim-both_cap_alphabetic]";

/** One-line auto-fit name for board identity rows. Visual only — set `aria-label` on the heading. */
export const StationNameTitle = ({
  name,
  className,
  end,
}: {
  name: string;
  className?: string;
  /** Sits after the name (e.g. disruption chips). The slot stays `flex-1` so auto-fit still measures leftover width. */
  end?: ReactNode;
}) => (
  <span
    className={cn(
      STATION_NAME_TITLE_SLOT_CLASS,
      end != null && "gap-x-1.5",
      className,
    )}
  >
    <span aria-hidden="true" className="contents">
      <StationName
        name={name}
        layout="auto"
        maxLines={1}
        allowAbbreviation
        allowScaleDown
        className={cn(
          STATION_NAME_TITLE_CLASS,
          end != null && "w-auto flex-none",
        )}
      />
    </span>
    {end}
  </span>
);

/** @deprecated Prefer `StationName`. */
export const StationNameLabel = StationName;

"use client";

import {
  forwardRef,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ClipboardEvent,
  type CSSProperties,
  type ReactNode,
} from "react";
import { useFindQuery } from "@/hooks/use-find-query";
import {
  isFindCovered,
  normalizeFindPhrase,
  phrasesToExpose,
} from "@/lib/tfl/find-coverage";

/** Chrome fires `beforematch` right before reveal but has no "unmatched" event. */
const REHIDE_DELAY_MS = 1500;

const FIND_PHRASE_WRAPPER_CLASS =
  "absolute left-1/2 top-full z-20 mt-1 -translate-x-1/2 whitespace-nowrap";
const FIND_PHRASE_CHIP_CLASS =
  "inline-block bg-foreground px-1.5 py-0.5 text-[11px] font-medium leading-none text-background";

const escapeFindText = (value: string): string =>
  value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");

/**
 * Contiguous phrases find-in-page can already hit in `root`.
 * `display: none` / `hidden` nodes are skipped; `<br>` starts a new phrase.
 */
export const collectFindPhrasesFromElement = (root: Element): string[] => {
  const phrases: string[] = [];
  let current = "";

  const flush = () => {
    const trimmed = normalizeFindPhrase(current);
    if (trimmed) phrases.push(trimmed);
    current = "";
  };

  const walk = (node: Node) => {
    if (node.nodeType === Node.TEXT_NODE) {
      current += node.textContent ?? "";
      return;
    }
    if (node.nodeType !== Node.ELEMENT_NODE) return;
    const el = node as Element;
    if (el.tagName === "BR") {
      flush();
      return;
    }
    if (el.hasAttribute("data-find-phrase")) return;
    if (typeof getComputedStyle === "function") {
      const display = getComputedStyle(el).display;
      if (display === "none") return;
    }
    const hidden = el.getAttribute("hidden");
    if (el.hasAttribute("hidden") && hidden !== "until-found") return;
    for (const child of el.childNodes) walk(child);
  };

  walk(root);
  flush();
  return phrases;
};

/**
 * Canonical text for Cmd/Ctrl+F when paint wraps (`<br>`) or abbreviates —
 * find-in-page cannot match a phrase across the `<br>` between visual lines.
 *
 * Three constraints shape this:
 * 1. React serialises `hidden` as a boolean (`hidden=""` → `display: none`,
 *    unsearchable), so `until-found` has to be written as raw markup.
 * 2. `until-found` is ignored on `display: inline` / `none`, hence `absolute`.
 * 3. Reveal walks a match's *ancestors*, so the text sits in a child.
 *
 * Firefox / Safari have no `until-found`; they do match `opacity: 0` text.
 *
 * There's also no native "find closed" event, so this re-hides a beat after
 * reveal and restarts the countdown if the browser matches it again.
 *
 * Chips stay out of the DOM when the current find query already highlights
 * the painted copy (e.g. "Liverpool St" on a wrapped "Liverpool Street").
 */
const FindPhrase = ({
  text,
  coveredPhrases,
}: {
  text: string;
  coveredPhrases: readonly string[];
}) => {
  const ref = useRef<HTMLSpanElement>(null);

  useLayoutEffect(() => {
    const el = ref.current?.firstElementChild;
    if (!(el instanceof HTMLElement)) return;

    if (!("onbeforematch" in document.body)) {
      el.removeAttribute("hidden");
      el.style.opacity = "0";
      return;
    }

    let rehideTimer: ReturnType<typeof setTimeout> | undefined;
    const handleBeforeMatch = () => {
      const selected = normalizeFindPhrase(
        document.getSelection()?.toString() ?? "",
      );
      if (selected && isFindCovered(selected, coveredPhrases)) {
        el.setAttribute("hidden", "until-found");
        return;
      }
      if (rehideTimer) clearTimeout(rehideTimer);
      rehideTimer = setTimeout(() => {
        el.setAttribute("hidden", "until-found");
      }, REHIDE_DELAY_MS);
    };

    el.addEventListener("beforematch", handleBeforeMatch);
    return () => {
      el.removeEventListener("beforematch", handleBeforeMatch);
      if (rehideTimer) clearTimeout(rehideTimer);
    };
  }, [coveredPhrases, text]);

  return (
    <span
      ref={ref}
      className="contents"
      data-find-phrase=""
      dangerouslySetInnerHTML={{
        __html: `<span hidden="until-found" data-find-phrase class="${FIND_PHRASE_WRAPPER_CLASS}"><span class="${FIND_PHRASE_CHIP_CLASS}">${escapeFindText(text)}</span></span>`,
      }}
    />
  );
};

export type FindableTextProps = {
  /** Canonical full text — used for aria-label, clipboard, and find-in-page. */
  text: string;
  /** Extra searchable variants not already covered by the visible paint. */
  aliases?: readonly string[];
  /**
   * Phrases find-in-page can already hit in the paint (`<br>`-split lines,
   * abbreviation completions). When omitted, read from the paint DOM.
   */
  coveredPhrases?: readonly string[];
  /** Set when the visible paint is already the exact contiguous `text` — skips the redundant reveal chip. */
  paintMatchesText?: boolean;
  /**
   * Escape hatch. Defaults to on — disable only for text that's intentionally
   * decorative/non-identity, and say why at the call site.
   */
  enableFind?: boolean;
  className?: string;
  style?: CSSProperties;
  children: ReactNode;
};

/**
 * Wraps identity text (station names, line names, stop names — anything a
 * user might expect to copy or find-in-page) so that when the visible paint
 * differs from the canonical string — real abbreviation, or a name split
 * across a `<br>` — Cmd/Ctrl+F and copy still resolve the full name.
 *
 * Hidden chips are mounted only for semantics the current find query cannot
 * already highlight in the paint. Plain CSS clipping (`truncate`,
 * `line-clamp`, `whitespace-nowrap`) never needs this: the DOM text is
 * unchanged, so the browser already finds and copies it correctly through
 * the clip. Reach for this only when the DOM text itself is not the
 * canonical string. See `.cursor/rules/findable-identity-text.mdc`.
 */
export const FindableText = forwardRef<HTMLSpanElement, FindableTextProps>(
  (
    {
      text,
      aliases = [],
      coveredPhrases: coveredPhrasesProp,
      paintMatchesText = false,
      enableFind = true,
      className,
      style,
      children,
    },
    ref,
  ) => {
    const paintRef = useRef<HTMLSpanElement>(null);
    const findQuery = useFindQuery();
    const [observedCovered, setObservedCovered] = useState<string[]>(
      () => coveredPhrasesProp?.slice() ?? [],
    );

    useLayoutEffect(() => {
      if (coveredPhrasesProp) return;
      const el = paintRef.current;
      if (!el) return;
      const read = () => setObservedCovered(collectFindPhrasesFromElement(el));
      read();
      const target = el.parentElement ?? el;
      const observer = new ResizeObserver(read);
      observer.observe(target);
      return () => observer.disconnect();
    }, [children, coveredPhrasesProp, findQuery, text]);

    const coveredPhrases = coveredPhrasesProp ?? observedCovered;

    const exposedPhrases = useMemo(() => {
      if (!enableFind) return [];
      const candidates = paintMatchesText ? [...aliases] : [text, ...aliases];
      return phrasesToExpose(candidates, coveredPhrases, findQuery);
    }, [aliases, coveredPhrases, enableFind, findQuery, paintMatchesText, text]);

    const handleCopy = (event: ClipboardEvent<HTMLSpanElement>) => {
      event.preventDefault();
      event.clipboardData.setData("text/plain", text);
    };

    return (
      <span
        ref={ref}
        className={className}
        style={style}
        aria-label={text}
        onCopy={handleCopy}
      >
        <span ref={paintRef} className="contents">
          {children}
        </span>
        {exposedPhrases.map((phrase) => (
          <FindPhrase
            key={phrase}
            text={phrase}
            coveredPhrases={coveredPhrases}
          />
        ))}
      </span>
    );
  },
);
FindableText.displayName = "FindableText";

import { formatStationName } from "@/lib/tfl/diagram-station";
import { applyStationAbbreviations } from "@/lib/tfl/station-abbreviations";

export {
  STATION_ABBREVIATIONS,
  applyStationAbbreviations,
} from "@/lib/tfl/station-abbreviations";

/** Measure text width in CSS px for a given font size. */
export type StationTextMeasure = (text: string, fontSizePx: number) => number;

export type StationLabelFormatOptions = {
  /** Available label width in CSS px. */
  maxWidth: number;
  /** Target font size in CSS px. */
  fontSize: number;
  /** Prefer one line; allow two when needed (default 2). */
  maxLines?: 1 | 2;
  /** Apply conservative TfL-style abbreviations only when needed. */
  allowAbbreviation?: boolean;
  /** Shrink type as a last resort when still too wide. */
  allowScaleDown?: boolean;
  /** Floor for scale-down (default 0.75). */
  minScale?: number;
  /**
   * Hardwired lines (e.g. horizontal diagram crowding fixes).
   * Skips auto word-break selection when provided.
   */
  forcedLines?: readonly string[];
};

export type StationLabelFormatResult = {
  /** Display lines (1 or 2). Never splits mid-word. */
  lines: string[];
  /** Applied scale relative to requested fontSize (1 = full size). */
  scale: number;
  /** True when an abbreviation was applied to fit. */
  abbreviated: boolean;
  /** True when the result fits within maxWidth at the applied scale. */
  fits: boolean;
  /** Normalised full name before line breaks. */
  displayName: string;
};

/**
 * Conservative abbreviations used only when enabled and required to fit.
 * Prefer official short forms already common on TfL diagrams.
 * @deprecated Import from `@/lib/tfl/station-abbreviations` — re-exported here.
 */
// STATION_ABBREVIATIONS re-exported above from station-abbreviations.

/** Minimum type scale before giving up on fit (documented contract). */
export const STATION_LABEL_MIN_SCALE = 0.75;

const tokenize = (name: string): string[] =>
  name
    .trim()
    .split(/\s+/)
    .filter(Boolean);

const applyAbbreviations = applyStationAbbreviations;

const lineWidth = (
  text: string,
  fontSize: number,
  measure: StationTextMeasure,
): number => measure(text, fontSize);

/**
 * All legal word-boundary splits into at most two lines.
 * Never breaks inside a token.
 */
export const stationLabelCandidates = (name: string): string[][] => {
  const tokens = tokenize(name);
  if (tokens.length === 0) return [[""]];
  if (tokens.length === 1) return [[tokens[0]!]];

  const candidates: string[][] = [[tokens.join(" ")]];
  for (let i = 1; i < tokens.length; i += 1) {
    candidates.push([tokens.slice(0, i).join(" "), tokens.slice(i).join(" ")]);
  }
  return candidates;
};

const scoreCandidate = (
  lines: string[],
  fontSize: number,
  maxWidth: number,
  measure: StationTextMeasure,
): { fits: boolean; balance: number; widest: number; lineCount: number } => {
  const widths = lines.map((line) => lineWidth(line, fontSize, measure));
  const widest = Math.max(...widths);
  const narrowest = Math.min(...widths);
  return {
    fits: widest <= maxWidth + 0.5,
    balance: widest - narrowest,
    widest,
    lineCount: lines.length,
  };
};

const pickBestCandidate = (
  candidates: string[][],
  fontSize: number,
  maxWidth: number,
  maxLines: 1 | 2,
  measure: StationTextMeasure,
): { lines: string[]; fits: boolean } => {
  const allowed =
    maxLines === 1
      ? candidates.filter((c) => c.length === 1)
      : candidates;

  let best = allowed[0] ?? [""];
  let bestScore = scoreCandidate(best, fontSize, maxWidth, measure);

  for (const candidate of allowed.slice(1)) {
    const score = scoreCandidate(candidate, fontSize, maxWidth, measure);
    const betterFit = score.fits && !bestScore.fits;
    const sameFit = score.fits === bestScore.fits;
    const preferFewerLines =
      sameFit && score.fits && score.lineCount < bestScore.lineCount;
    const betterBalance =
      sameFit &&
      score.fits &&
      score.lineCount === bestScore.lineCount &&
      score.balance < bestScore.balance;
    const lessOverflow =
      sameFit &&
      !score.fits &&
      score.widest < bestScore.widest;

    if (betterFit || preferFewerLines || betterBalance || lessOverflow) {
      best = candidate;
      bestScore = score;
    }
  }

  return { lines: best, fits: bestScore.fits };
};

/**
 * Deterministic station-name layout for diagrams and the typography lab.
 * Prefer full one-line → balanced two-line → abbreviated → scale-down.
 */
export const formatStationLabel = (
  rawName: string,
  measure: StationTextMeasure,
  options: StationLabelFormatOptions,
): StationLabelFormatResult => {
  const maxLines = options.maxLines ?? 2;
  const allowAbbreviation = options.allowAbbreviation ?? false;
  const allowScaleDown = options.allowScaleDown ?? true;
  const minScale = options.minScale ?? STATION_LABEL_MIN_SCALE;
  const displayName = formatStationName(rawName);
  const maxWidth = Math.max(1, options.maxWidth);
  const fontSize = Math.max(1, options.fontSize);

  if (options.forcedLines && options.forcedLines.length > 0) {
    const lines = [...options.forcedLines];
    const sized = fontSize;
    const widest = Math.max(
      ...lines.map((line) => lineWidth(line, sized, measure)),
    );
    return {
      lines,
      scale: 1,
      abbreviated: lines.join(" ") !== displayName,
      fits: widest <= maxWidth + 0.5,
      // Always the canonical single-line name — not the joined (possibly
      // abbreviated) visual lines. Copy / aria use this via formatStationName.
      displayName,
    };
  }

  const tryName = (
    name: string,
    abbreviated: boolean,
    scale: number,
  ): StationLabelFormatResult => {
    const sized = fontSize * scale;
    const { lines, fits } = pickBestCandidate(
      stationLabelCandidates(name),
      sized,
      maxWidth,
      maxLines,
      measure,
    );
    return {
      lines,
      scale,
      abbreviated,
      fits,
      displayName: name,
    };
  };

  // 1. Full name at full size
  let result = tryName(displayName, false, 1);
  if (result.fits) return result;

  // 2. Abbreviations at full size
  if (allowAbbreviation) {
    const abbreviatedName = applyAbbreviations(displayName);
    if (abbreviatedName !== displayName) {
      result = tryName(abbreviatedName, true, 1);
      if (result.fits) return result;
    }
  }

  // 3. Scale down (full name first, then abbreviated)
  let smallest: StationLabelFormatResult = result;
  if (allowScaleDown && minScale < 1) {
    const steps = 8;
    for (let i = 1; i <= steps; i += 1) {
      const scale = Math.max(minScale, 1 - (i / steps) * (1 - minScale));
      const full = tryName(displayName, false, scale);
      if (full.fits) return full;
      if (full.scale < smallest.scale) smallest = full;

      if (allowAbbreviation) {
        const abbreviatedName = applyAbbreviations(displayName);
        if (abbreviatedName !== displayName) {
          const abbr = tryName(abbreviatedName, true, scale);
          if (abbr.fits) return abbr;
          // Prefer the shorter visual when both overflow at the same scale.
          if (
            abbr.scale < smallest.scale ||
            (abbr.scale === smallest.scale && abbr.abbreviated)
          ) {
            smallest = abbr;
          }
        }
      }
    }
  }

  // Nothing fitted — keep the smallest attempt, never bounce back to full size.
  return smallest;
};

/**
 * Character-count fallback measure for SSR / tests.
 * Approximate Hammersmith One average advance ≈ 0.55em.
 */
export const approximateStationMeasure: StationTextMeasure = (
  text,
  fontSizePx,
) => text.length * fontSizePx * 0.55;

/** Build a canvas-backed measure for the live document font. */
export const createCanvasStationMeasure = (
  fontFamily: string,
  fontWeight = "400",
): StationTextMeasure => {
  if (typeof document === "undefined") return approximateStationMeasure;

  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) return approximateStationMeasure;

  return (text, fontSizePx) => {
    ctx.font = `${fontWeight} ${fontSizePx}px ${fontFamily}`;
    return ctx.measureText(text).width;
  };
};

/** Resolve the computed sans font stack from an element (or document body). */
export const resolveSansFontFamily = (el?: Element | null): string => {
  if (typeof window === "undefined") {
    return "Hammersmith One, system-ui, sans-serif";
  }
  const target = el ?? document.body;
  const family = getComputedStyle(target).fontFamily;
  return family || "Hammersmith One, system-ui, sans-serif";
};

export type DiagramConnection = {
  id: string;
  name: string;
  /** Hex colour for flag box; defaults to muted if omitted. */
  color?: string;
  /** When true, use corporate blue text (Circle / H&C / W&C). */
  darkText?: boolean;
};

export type DiagramStation = {
  id: string;
  name: string;
  /** Show interchange ring instead of a tick. */
  interchange?: boolean;
  /** Optional connecting-line flag boxes (Tube / TfL modes — not National Rail). */
  connections?: DiagramConnection[];
  /**
   * National Rail interchange — rendered as the NR pictogram beside the name,
   * not as a §9 text flag.
   */
  nationalRail?: boolean;
};

/** Adjacent route segment state for horizontal diagrams. */
export type DiagramSegmentState = "normal" | "out-of-use";

export type DiagramSegment = {
  fromStationId: string;
  toStationId: string;
  state: DiagramSegmentState;
};

/**
 * Parentheticals that disambiguate which stop / line — strip these.
 * Keep place-name parentheses such as Kensington (Olympia).
 */
const LINE_DISAMBIGUATION_PARENS =
  /\s*\((?:[^)]*\b(?:Line|Lines|Bakerloo|Central|Circle|District|Piccadilly|Northern|Victoria|Jubilee|Metropolitan|Elizabeth|H&C|Dist|Picc|London)\b[^)]*)\)/gi;

/** Short display name for diagrams (drop common TfL suffixes + line brackets). */
export const formatStationName = (name: string): string => {
  const raw = typeof name === "string" ? name : name == null ? "" : String(name)
  let next = raw
    .replace(/\s+Underground Station$/i, "")
    .replace(/-Underground(?:\s+Station)?$/i, "")
    .replace(/\s+DLR Station$/i, "")
    .replace(/\s+Rail Station$/i, "")
    .replace(/\s+Tram (?:Stop|Station)$/i, "")
    .replace(/\s+Station$/i, "")
    .trim();

  next = next.replace(LINE_DISAMBIGUATION_PARENS, "").trim();

  // Heathrow Terminals 2 & 3 → 2&3 (no spaces around &)
  next = next.replace(/(\d+)\s*&\s*(\d+)/g, "$1&$2");

  return next.replace(/\s+/g, " ").trim();
};

export const isLikelyInterchange = (stop: {
  lines?: { id?: string | null }[] | null;
  modes?: string[] | null;
}): boolean => {
  const lineCount = stop.lines?.filter((l) => l.id).length ?? 0;
  if (lineCount > 1) return true;
  const modes = stop.modes?.filter(Boolean) ?? [];
  return modes.length > 1;
};

import { formatStationName } from "@/lib/tfl/diagram-station";
import {
  neededFindPhrases,
  normalizeFindPhrase,
} from "@/lib/tfl/find-coverage";
import { STATION_ABBR_FIND_COMPLETIONS } from "@/lib/tfl/station-abbreviations";

export { STATION_ABBR_FIND_COMPLETIONS } from "@/lib/tfl/station-abbreviations";
export {
  isFindCovered,
  neededFindPhrases,
  normalizeFindPhrase,
  shouldExposeFindPhrase,
} from "@/lib/tfl/find-coverage";

const APOSTROPHE_RE = /[\u2018\u2019\u02BC']/g;

export const stripStationApostrophes = (value: string): string =>
  value.replace(APOSTROPHE_RE, "");

/** Normalise curly apostrophes to ASCII for alternate find queries. */
export const normalizeStationApostrophes = (value: string): string =>
  value.replace(/[\u2018\u2019\u02BC]/g, "'");

/**
 * Official copy / aria form: single line, full words, no diagram line breaks.
 */
export const stationCopyName = (
  rawName: string,
  accessibleName?: string,
): string => {
  const next = (accessibleName ?? formatStationName(rawName))
    .replace(/\s+/g, " ")
    .trim();
  return next;
};

/** `&` between words → `and` (keeps Heathrow-style `2&3` as `2 and 3`). */
export const stationAndForm = (value: string): string =>
  value
    .replace(/(\d+)\s*&\s*(\d+)/g, "$1 and $2")
    .replace(/\s*&\s*/g, " and ")
    .replace(/\s+/g, " ")
    .trim();

export const findCompletionForToken = (token: string): string | undefined => {
  if (!token || token === "&") return undefined;
  const direct = STATION_ABBR_FIND_COMPLETIONS[token];
  if (direct) return direct;
  const matched = Object.entries(STATION_ABBR_FIND_COMPLETIONS).find(
    ([abbr]) => abbr.toLowerCase() === token.toLowerCase(),
  );
  return matched?.[1];
};

/**
 * Visual line text as find-in-page would see it after abbr completions
 * (e.g. "Liverpool St" → "Liverpool Street").
 */
export const expandStationLineForFind = (line: string): string =>
  line
    .split(/(\s+|&)/)
    .map((part) => {
      const completion = findCompletionForToken(part);
      return completion ? `${part}${completion}` : part;
    })
    .join("");

/**
 * Phrases already contiguous in the DOM for Cmd/Ctrl+F.
 * Multi-line paint inserts `<br>`, which breaks matching across lines — so a
 * joined expansion is NOT treated as covered when there is more than one line.
 */
export const stationFindCoveredPhrases = (
  visualLines: readonly string[],
): string[] => {
  const covered: string[] = [];
  for (const line of visualLines) {
    const trimmed = normalizeFindPhrase(line);
    if (trimmed) covered.push(trimmed);
    const expanded = normalizeFindPhrase(expandStationLineForFind(line));
    if (expanded) covered.push(expanded);
  }
  if (visualLines.length === 1) {
    const only = visualLines[0] ?? "";
    const joined = normalizeFindPhrase(expandStationLineForFind(only));
    if (joined) covered.push(joined);
  }
  return covered;
};

/**
 * Extra phrases to expose to Cmd/Ctrl+F when they are not already covered by
 * contiguous DOM text (visible lines + inline abbreviation completions).
 * StationName renders these with `hidden="until-found"` (findable; shows on match).
 *
 * Contract: copy / aria / find all keep the canonical single-line full name,
 * even when the paint wraps or abbreviates (`<br>` breaks cross-line find).
 */
export const stationFindAliases = (
  copyName: string,
  visualLines: readonly string[],
): string[] => {
  const covered = stationFindCoveredPhrases(visualLines);
  const visualJoined = normalizeFindPhrase(visualLines.join(" "));

  return neededFindPhrases(
    [
      copyName,
      stationAndForm(copyName),
      normalizeStationApostrophes(copyName),
      stripStationApostrophes(copyName),
      stationAndForm(stripStationApostrophes(copyName)),
      normalizeStationApostrophes(stationAndForm(copyName)),
      stationAndForm(visualJoined),
      stripStationApostrophes(visualJoined),
      normalizeStationApostrophes(visualJoined),
    ],
    covered,
  );
};

/**
 * Single source of truth for TfL-style station-name abbreviations.
 * Drives both visual shortening and Cmd/Ctrl+F completions.
 */

export type StationAbbreviationEntry = {
  /** Full word as it appears in canonical names (e.g. "Street"). */
  full: string;
  /** Diagram short form (e.g. "St"). */
  short: string;
  /**
   * Invisible suffix appended after `short` so find-in-page matches `full`
   * (e.g. "reet" → "Street").
   */
  findCompletion: string;
};

